const SEC='https://www.investor.gov/introduction-investing/general-resources/news-alerts/alerts-bulletins/investor-bulletins-63';
const FINRA='https://www.finra.org/investors/investing/investment-products/options';
const PRICE='https://www.optionseducation.org/optionsoverview/options-pricing';
const GREEKS='https://prd-web.optionseducation.org/advancedconcepts/volatility-the-greeks';
const COVERED='https://www.optionseducation.org/strategies/all-strategies/covered-call-buy-write';
const CSP='https://www.optionseducation.org/strategies/all-strategies/cash-secured-put';
const SPREAD='https://www.optionseducation.org/strategies/all-strategies/bull-call-spread-debit-call-spread';
// Original examples: USD, standard unadjusted 100-share equity contracts, no fees.
const make=(id,title,explanation,example,exercise,answer,hint,answerExplanation,source,question,options,correct)=>({id,title,explanation,example,exercise,answer,unit:'Enter a number',hint,answerExplanation,source,knowledgeCheck:{question,options,answer:correct,explanation:options[correct]+". "+explanation}});
export const lessons=[
make('stocks-options','Stocks versus options','Stock is ownership; an option is an expiring contract. The buyer gets a right and the seller takes an obligation. Leverage magnifies risk.','10 shares at $50 cost $500. A $2 option costs $200 per standard contract.','Dollar cost of 10 shares at $50?',500,'Shares times price.','10 × $50 = $500.',SEC,'Which has a fixed expiration?',['A stock share itself','An option'],1),
make('calls-puts','Calls and puts','Calls give buyers the right to buy at strike; puts give buyers the right to sell. Buying a put is different from shorting stock.','A $50 put at stock $44 has $6 intrinsic value per share.','Intrinsic value per share of that put?',6,'max(strike minus stock, 0).','$50 − $44 = $6; profit also subtracts premium.',SEC,'A call buyer may…',['Buy at strike','Sell at strike'],0),
make('contract-terms','Strike, premium, expiration & size','Strike is exercise price; premium is option price, usually per share; expiration ends the right. This app uses 100-share contracts. Real adjusted contracts can differ.','2 contracts at $1.25 cost $250.','Dollar cost of 3 contracts at $1.50?',450,'Quantity × 100 × premium.','3 × 100 × $1.50 = $450.',FINRA,'A $1 quote costs…',['$1 per contract','$100 per standard contract'],1),
make('bid-ask','Bid–ask spreads','Bid is a quoted buying price; ask is a quoted selling price. Here purchases use ask, sales use bid. Midpoint marks do not promise a fill; actual liquidity is not simulated.','Buy at $2.10 ask; sell at $1.90 bid: $20 loss per contract.','Buy one at $3.20, sell at $3.00. Positive dollar loss?',20,'Price difference × 100.','($3.20 − $3.00) × 100 = $20.',FINRA,'Purchases here use…',['Bid','Ask'],1),
make('intrinsic-extrinsic','Intrinsic & extrinsic value','Intrinsic is exercise value: max(stock minus strike, 0) for calls, max(strike minus stock, 0) for puts. Extrinsic is premium beyond intrinsic.','A $100 call at stock $104 and premium $6 has $4 intrinsic, $2 extrinsic.','Premium $7, intrinsic $5: extrinsic per share?',2,'Premium minus intrinsic.','$7 − $5 = $2.',PRICE,'Extrinsic at expiration is…',['Zero','Always positive'],0),
make('moneyness','Moneyness is not profit','In the money means positive intrinsic value; at the money means near strike; out of the money means no intrinsic. These labels ignore your entry price.','A $100 call at $101 is in the money but, bought at $4, loses $3 per share at expiration.','Intrinsic per share of that call?',1,'Stock minus strike, floored at zero.','$101 − $100 = $1.',PRICE,'Can an in-the-money trade lose?',['Yes','No'],0),
make('break-even','Break-even at expiration','Long call break-even is strike plus premium; long put break-even is strike minus premium. Before expiration, time value and volatility affect resale value too.','A $50 call bought at $3 breaks even at $53 at expiration.','A $60 put costs $2.50. Expiration break-even stock price?',57.5,'Put strike minus premium.','$60 − $2.50 = $57.50.',SEC,'Must stock reach expiration break-even for an earlier profitable sale?',['Always','No'],1),
make('greeks','Delta, gamma, theta & vega','Greeks estimate sensitivity. Delta: premium change per $1 stock move. Gamma: delta change per $1. Theta here: premium change per calendar day. Vega: premium change per one percentage-point IV change. All are per share.','Delta 0.50 estimates $0.50 more premium for a $1 stock rise, other inputs fixed.','Using only delta 0.40, one-contract dollar gain for a $2 rise?',80,'Delta × stock change × 100.','0.40 × $2 × 100 = $80. Other inputs can change the result.',GREEKS,'Which measures time sensitivity?',['Theta','Vega'],0),
make('volatility','IV & volatility crush','IV is volatility inferred from option prices. It concerns movement size, not direction. Falling IV after an event can hurt long options despite a favorable stock move.','Fixed vega 0.08 and a 10 percentage-point IV drop estimate $0.80 less premium per share.','Positive estimated dollar loss for one contract?',80,'0.08 × 10 × 100.','$80. Fixed vega is a local estimate, not exact repricing.',GREEKS,'Does high IV guarantee a rise?',['Yes','No'],1),
make('long-options','Long calls & long puts','Long means bought. Calls benefit from sufficiently large rises; puts from sufficiently large falls. Either can lose all premium. Call upside is unlimited in theory; put upside ends at stock zero.','A $100 put bought for $4 pays $10 at stock $90 expiration.','One-contract dollar profit in that example?',600,'(Payoff minus premium) × 100.','($10 − $4) × 100 = $600.',FINRA,'Maximum fully paid long-option loss?',['Premium paid','Unlimited'],0),
make('secured-options','Covered calls & cash-secured puts','Covered calls commit 100 owned shares per contract and cap upside; stock downside remains. Cash-secured puts reserve cash to buy shares if assigned. This app reserves strike × 100 per put.','100 shares at $50 plus a short $55 call at $2: maximum total gain $700, maximum loss $4,800.','Gross dollar collateral for one $40 put?',4000,'Strike × 100.','$40 × 100 = $4,000. Premium does not remove downside.',CSP,'Does covered-call income erase stock downside?',['Yes','No'],1),
make('spreads','Debit & credit spreads','Vertical legs match underlying, expiration and quantity, with different strikes. Debit means payment; credit means receipt. Debit risk is payment. Credit risk is width × 100 minus credit per spread. Real assignment adds complexity.','A $100/$105 bull call spread at $2 has $200 maximum loss and $300 gain.','A $5-wide credit spread receives $1.50 per share. Maximum dollar loss?',350,'(Width minus credit) × 100.','($5 − $1.50) × 100 = $350.',SPREAD,'What matches on vertical legs?',['Underlying, expiration, quantity','Strike'],0),
make('expiration','Exercise, assignment & expiration','Exercise invokes the buyer’s right; assignment obligates the seller. American-style equity options allow early exercise. Real exercise usually delivers shares. This app uses educational expiration cash settlement, not brokerage assignment.','A $100 call at stock $108 has $800 terminal payoff before premium.','One $50 put ends at stock $46. Dollar payoff?',400,'max(strike minus stock, 0) × 100.','($50 − $46) × 100 = $400. Profit subtracts premium.',SEC,'Can real American-style options be assigned early?',['Yes','No'],0),
make('position-sizing','Position sizing & your journal','Choose a hypothetical loss budget first. Journal reasoning, expected move, holding period, planned exit, risk and reflection. Assess process as well as profit. No percentage suits everyone.','A chosen $300 budget permits two contracts risking $120 each, not three.','Chosen $500 loss budget, $200 maximum loss per spread: how many whole spreads?',2,'Divide and round down.','floor(500 / 200) = 2, risking $400.',FINRA,'Review which trades?',['Only winners','Every trade’s risk and reasoning'],1)
];
const task=(id,title,objective,startingConditions,exercise,answer,hint,answerExplanation,source)=>({id,title,objective,startingConditions,explanation:objective,example:startingConditions,exercise,answer,unit:'Enter a number',hint,answerExplanation,source});
// Deterministic isolated exercises; no attempt executes practice-account trades.
export const challenges=[
task('contract-cost','The multiplier matters','Calculate the complete order debit.','3 calls at $2.40 ask; 100 shares each; no fees.','Total dollar debit?',720,'3 × 2.40 × 100.','$720, also the maximum loss on these long calls.',FINRA),
task('call-breakeven','Above strike is not enough','Find expiration break-even.','One $100 call bought at $4.25 per share.','Break-even stock price?',104.25,'Strike plus premium.','$100 + $4.25 = $104.25 at expiration.',SEC),
task('time-decay','The sideways clock','Measure loss from supplied theoretical marks.','Stock stays $100; IV unchanged; one call declines from $3.00 to $2.40 as time passes. Ignore bid–ask.','Positive dollar loss?',60,'(3 − 2.40) × 100.','$60 loss. Theta changes; do not assume constant daily decay.',GREEKS),
task('favorable-loss','Right direction, losing trade','Separate direction from expiration profit.','One $100 call bought at $5 when stock is $100; stock rises to $103 at expiration.','Dollar P/L? Negative for a loss.',-200,'(max(103 − 100, 0) − 5) × 100.','$300 payoff − $500 premium = −$200.',PRICE),
task('call-vs-spread','Trade upside for lower cost','Compare maximum loss.','One $100 call costs $5 ($500). One $100/$110 bull call spread costs $3 ($300).','How many dollars less maximum loss does the spread have?',200,'Call cost minus spread debit.','$200 less risk. Spread maximum gain is $700; call upside is unlimited in theory.',SPREAD),
task('put-collateral','Reserve before selling','Reserve sufficient gross security.','Sell 2 puts at $45 strike for $1.50 per share. App reserves full strike × 100 cash.','Gross dollar collateral?',9000,'2 × 45 × 100.','$9,000 reserved. $300 premium lowers maximum economic loss to $8,700 at stock zero.',CSP),
task('covered-call-risk','Income still has downside','Calculate whole-position downside.','Buy 100 shares at $50; sell a $55 call for $2. Maximum upside $700; no fees.','Positive maximum dollar loss if stock becomes worthless?',4800,'Stock cost minus premium.','$5,000 − $200 = $4,800. Those reserved shares cannot secure another call.',COVERED),
task('volatility-crush','After the event','Recognize a loss despite a favorable move.','Buy one call at $6. Stock rises slightly after an event but IV falls sharply. Given executable bid is $3.50.','Dollar P/L if sold at that bid?',-250,'(3.50 − 6) × 100.','−$250. Falling IV and time can outweigh a small favorable stock move.',GREEKS)
];

